-- Rollup detention_facility_daily of detention_occurrences, generated by keel's analytics/rollup. Do not edit; change the declaration and generate again.
CREATE TABLE IF NOT EXISTS keel_rollup_dirty (
    rollup text COLLATE "C" NOT NULL,
    tenant_key text COLLATE "C" NOT NULL,
    bucket timestamptz NOT NULL,
    xid xid8 NOT NULL,
    marked_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (rollup, tenant_key, bucket, xid)
);
CREATE INDEX IF NOT EXISTS keel_rollup_dirty_marked ON keel_rollup_dirty (marked_at);
CREATE TABLE IF NOT EXISTS keel_rollup_state (
    rollup text COLLATE "C" PRIMARY KEY,
    ready_at timestamptz NOT NULL
);
DELETE FROM keel_rollup_state WHERE rollup = 'detention_facility_daily';
DELETE FROM keel_rollup_dirty WHERE rollup = 'detention_facility_daily';
DO $keel$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_class WHERE oid = to_regclass('"detention_facility_daily"') AND obj_description(oid, 'pg_class') = 'keel rollup detention_facility_daily of detention_occurrences') THEN
        DROP TABLE "detention_facility_daily";
    END IF;
END
$keel$;
