    IF TG_OP = 'INSERT' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_facility_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_new n
        ON CONFLICT DO NOTHING;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_facility_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_old n
        ON CONFLICT DO NOTHING;
    ELSE
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'detention_facility_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."clock_start_at"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM ((SELECT "business_unit_id", "organization_id", "location_id", "stop_type", "schedule_type", "handling", "appointment_start", "arrived_at", "clock_start_at", "notice_deadline_at", "is_open", "arrived_late", "free_minutes_granted", "raw_dwell_minutes", "gross_amount", "billable_amount", "driver_pay_amount", "net_margin", "status", "notice_sent_at", "suppressed_by_gate", "waived_amount" FROM keel_old EXCEPT ALL SELECT "business_unit_id", "organization_id", "location_id", "stop_type", "schedule_type", "handling", "appointment_start", "arrived_at", "clock_start_at", "notice_deadline_at", "is_open", "arrived_late", "free_minutes_granted", "raw_dwell_minutes", "gross_amount", "billable_amount", "driver_pay_amount", "net_margin", "status", "notice_sent_at", "suppressed_by_gate", "waived_amount" FROM keel_new) UNION ALL (SELECT "business_unit_id", "organization_id", "location_id", "stop_type", "schedule_type", "handling", "appointment_start", "arrived_at", "clock_start_at", "notice_deadline_at", "is_open", "arrived_late", "free_minutes_granted", "raw_dwell_minutes", "gross_amount", "billable_amount", "driver_pay_amount", "net_margin", "status", "notice_sent_at", "suppressed_by_gate", "waived_amount" FROM keel_new EXCEPT ALL SELECT "business_unit_id", "organization_id", "location_id", "stop_type", "schedule_type", "handling", "appointment_start", "arrived_at", "clock_start_at", "notice_deadline_at", "is_open", "arrived_late", "free_minutes_granted", "raw_dwell_minutes", "gross_amount", "billable_amount", "driver_pay_amount", "net_margin", "status", "notice_sent_at", "suppressed_by_gate", "waived_amount" FROM keel_old)) n
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NULL;
END
$keel$;
CREATE OR REPLACE TRIGGER "keel_rollup_detention_facility_daily_insert" AFTER INSERT ON "detention_occurrences" REFERENCING NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_facility_daily();
CREATE OR REPLACE TRIGGER "keel_rollup_detention_facility_daily_update" AFTER UPDATE ON "detention_occurrences" REFERENCING OLD TABLE AS keel_old NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_facility_daily();
CREATE OR REPLACE TRIGGER "keel_rollup_detention_facility_daily_delete" AFTER DELETE ON "detention_occurrences" REFERENCING OLD TABLE AS keel_old FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_detention_facility_daily();
