WITH marked AS (INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid) SELECT DISTINCT 'detention_facility_daily', replace(replace(coalesce(s."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(s."organization_id"::text, ''), '\', '\\'), '/', '\/'), '-infinity'::timestamptz, pg_current_xact_id() FROM "detention_occurrences" s ON CONFLICT DO NOTHING)
